{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "Launch template does not enable instance volume encryption",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "HIGH",
      "explanation": "The launch template does not specify encryption for the root block device or any additional block devices. Unencrypted volumes can expose sensitive data if compromised."
    }
  ],
  "patched_code": "resource "aws_launch_template" "changeme_simple_asg_launch_template_nlb" {
  name                   = "changeme-simple-asg-launch-template-nlb"
  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id
  instance_type          = "t2.micro"
  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]
  user_data              = filebase64("${path.module}/user_data.sh")

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      delete_on_termination = true
      encrypted             = true
    }
  }
}",
  "fix_summary": "Added a block_device_mappings block to enable encryption for the root volume of the instance, ensuring data at rest is protected."
}
